"""CCDV-F group 1: Model Selection and Optimization (Domain 5), Evaluation/Testing/Debugging (Domain 4) and Claude Code (Domain 3).

Written against the Claude Certified Developer - Foundations exam guide (version 1.0, effective July 2026) and verified in
October 2026 against the current Claude API, Claude Code and Agent SDK documentation. Group 1 owns: flashcards for the
testing and code categories (ids f1201..; the models flashcards live in data/ccdv_b1.py), all questions for models, testing and
code (ids q1101.., msq1101.., tf1101..), two lessons, three mad libs, two sequences, four compare items and three cheat-sheet
sections. Options are written with the best answer first and permuted at the end of the module (deterministic seed per item id).
"""


def _fc(i, cat, front, back, detail):
    return {'id': i, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(i, cat, question, answer, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


_CO = 'code'
_TE = 'testing'
_MO = 'models'

FLASHCARDS = []
QUESTIONS = []
LESSONS = []
MADLIBS = []
SEQUENCES = []
CASE_STUDIES = []
COMPARE = []
CLI_CHALLENGES = []
CHEAT_SHEET = []


