# ---------------- finalize: deterministic option order ----------------
# Options are written with the best answer first for readability; this pass permutes every
# multiple-choice and multiple-select item and every mad-lib blank with a seed derived from the
# item id, so the shipped order is stable between builds and the answer key stays correct.
import random as _random
import zlib as _zlib


def _order(seed, n):
    order = list(range(n))
    _random.Random(_zlib.crc32(seed.encode('utf-8'))).shuffle(order)
    return order


def _permute(q):
    opts = q.get('options')
    if not opts or q.get('type') not in ('mc', 'ms'):
        return
    order = _order(q['id'], len(opts))
    q['options'] = [opts[i] for i in order]
    if q['type'] == 'mc':
        q['correct'] = order.index(q['correct'])
    else:
        q['correct'] = sorted(order.index(i) for i in q['correct'])


for _q in QUESTIONS:
    _permute(_q)
for _ml in MADLIBS:
    for _b in _ml['blanks']:
        _o = _order(_ml['id'] + ':' + _b['key'], len(_b['options']))
        _b['options'] = [_b['options'][i] for i in _o]
        _b['correct'] = _o.index(_b['correct'])
